tests.code:
% name: Whole numbers
% points: 2
assert(rect_area(3, 4) == 12, 'rect_area(3, 4) should be 12');
assert(rect_area(1, 1) == 1, 'rect_area(1, 1) should be 1');

% name: Arrays of sizes
% points: 2
a = rect_area([1 2 3], [4 5 6]);
assert(isequal(a, [4 10 18]), 'rect_area([1 2 3], [4 5 6]) should be [4 10 18]');

% name: The class file
% points: 3
m = mean_score('scores.csv');
assert(abs(m - 75) < 1e-9, 'The average of the scores in scores.csv should be 75');

% name: Another file
% points: 3
writematrix([1 10; 2 20; 3 60], 'other.csv');
m = mean_score('other.csv');
assert(abs(m - 30) < 1e-9, 'For scores 10, 20 and 60 the average should be 30');
